parameters.checklist:
[
  {
    "id": "invariants_registered",
    "assert": "invariants_registered",
    "cmd": "${spec_tools}/criterion ${spec_tools}/spec/spec-check invariants invariants_registered --spec-dir ${spec_dir}",
    "origin": "pe-profile:spec-decompose@1.0.0"
  },
  {
    "id": "each_invariant_grounded",
    "assert": "each_invariant_grounded",
    "cmd": "${spec_tools}/criterion ${spec_tools}/spec/spec-check invariants each_invariant_grounded --spec-dir ${spec_dir}",
    "origin": "pe-profile:spec-decompose@1.0.0"
  },
  {
    "id": "each_invariant_falsifiable",
    "assert": "each_invariant_falsifiable",
    "cmd": "${spec_tools}/criterion ${spec_tools}/spec/spec-check invariants each_invariant_falsifiable --spec-dir ${spec_dir}",
    "origin": "pe-profile:spec-decompose@1.0.0"
  }
]

[
  {
    "id": "invariants-review-verdict",
    "assert": "the cold reviewer returned APPROVE",
    "cmd": "test \"$(jq -r .verdict ${spec_dir}/review-invariants.json)\" = APPROVE",
    "origin": "pe-profile:spec-decompose@1.0.0"
  },
  {
    "id": "invariants-review-is-substantive",
    "assert": "the review carries at least 40 words of findings",
    "cmd": "test \"$(jq -r '.findings // \"\" | length' ${spec_dir}/review-invariants.json)\" -ge 200",
    "origin": "pe-profile:spec-decompose@1.0.0"
  },
  {
    "id": "invariants-review-engages-with-the-diff",
    "paths": [
      "${spec_dir}/invariants.json"
    ],
    "context": [
      "${spec_dir}/review-invariants.json"
    ],
    "judge": "Does this review apply GROUNDED (each invariant's grounding is really in the frozen intent) and TOOTHED (each falsifier is a concrete observable, not a restatement) to the invariants in the diff, by id? FAIL if it approves or rejects without naming specific items from the diff, if it makes a claim the diff does not support, if it is generic enough to apply to any artifact of this kind, or if it leaves part of the diff unjudged.",
    "diff": true,
    "blocking": true,
    "origin": "pe-profile:spec-decompose@1.0.0"
  }
]

